import firstImage from "../img/firstumage.png";
import doubleImage from "../img/doubleimage.png";
import tripleImage from "../img/tripleimage.png";
import lastImage from "../img/lastimage.png";

function NatureSection() {
  return (
    <section className="nature-section">
      <h2>Beautiful nature</h2>

      <div className="nature-gallery">
        <img
          className="nature-photo nature-photo-1"
          src={firstImage}
          alt="Nature 1"
        />

        <img
          className="nature-photo nature-photo-2"
          src={doubleImage}
          alt="Nature 2"
        />

        <img
          className="nature-photo nature-photo-3"
          src={tripleImage}
          alt="Nature 3"
        />

        <img
          className="nature-photo nature-photo-4"
          src={lastImage}
          alt="Nature 4"
        />
      </div>
    </section>
  );
}

export default NatureSection;
